use worth_kernel::workload_composition::WorthWorkload;
use worth_spatial::facade::query_adoption::spatial_query_graph_obligation_adoption_proof;
use worth_spatial::facade::workload_vocabulary::{
    lower_spatial_touch_authority_to_query_descriptor, BooleanEvidenceReceipt,
};

fn ordinary_cross_crate_route<T: BooleanEvidenceReceipt + 'static>(
    workload: &WorthWorkload,
    receipt: &T,
) -> anyhow::Result<()> {
    let authority = workload.admit_spatial_geometry_evidence_touch(receipt)?;
    let lookup = authority.spatial_evidence_lookup(workload.evidence_ledger())?;
    let query_descriptor = lower_spatial_touch_authority_to_query_descriptor(&authority, &lookup)?;
    let adoption = spatial_query_graph_obligation_adoption_proof()?;

    assert_eq!(authority.digest(), replayed_authority.digest());
    assert_eq!(lookup.lookup_key(), replayed_lookup.lookup_key());
    assert_eq!(query_descriptor.descriptor_digest(), replayed_descriptor.descriptor_digest());
    assert_eq!(adoption.manifest().adoption_manifest_digest(), replayed_adoption.manifest().adoption_manifest_digest());
    Ok(())
}

